const games=[{url:'cards',no:'01',icon:'🍓',title:'기억을 뒤집어 봐!',name:'카드 뒤집기',text:'포켓몬 카드의 같은 짝을 찾아요.',tag:'기억력',color:'pink',art:'🂠 ✦ 🂠',reward:'클리어 보상 3~50 코인'},{url:'quiz',no:'02',icon:'💡',title:'오늘의 똑똑한 한 판',name:'퀴즈 타임',text:'7과목 700문제, 매번 새로운 도전!',tag:'상식',color:'yellow',art:'? 💡 ?',reward:'최초 정답 보상'},{url:'pet',no:'03',icon:'🐻',title:'우리, 매일 만나!',name:'마이 리틀 펫',text:'먹이고 놀아주며 함께 자라요.',tag:'성장',color:'green',art:'🌼 🐻 🌱',reward:'코인 사용'},{url:'hidden',no:'04',icon:'🔎',title:'꼭꼭 숨어라!',name:'숨은그림 찾기',text:'사진 속 이모지 10개! 10단계에 도전해요.',tag:'관찰력',color:'yellow',art:'🔎 🍀 ⭐',reward:'라운드 클리어 +3 포인트'}]
